"""Example tests for the mocked AWS inventory (generated by SkyForge AI).

They assert the resources Terraform declares actually exist in the mock, which keeps the fixtures and
the infrastructure in sync. Extend them with your real business assertions.
"""

from .conftest import TERRAFORM_RESOURCES


def test_ec2_fixture_is_available(mock_ec2):
    assert mock_ec2['names'] == ['api-a-instance', 'api-b-instance', 'worker-instance', 'report-a-instance', 'report-b-instance', 'bastion-instance']


def test_terraform_iam_resources_exist(mock_iam):
    client = mock_iam["client"]
    existing = [r['RoleName'] for r in client.list_roles()['Roles']]
    for name in ['orderflow-lambda-role']:
        assert name in existing, f"{name} is declared in Terraform but missing from the mock"


def test_terraform_lambda_resources_exist(mock_lambda):
    client = mock_lambda["client"]
    existing = [f['FunctionName'] for f in client.list_functions()['Functions']]
    for name in ['orderflow-ingest', 'orderflow-invoice', 'orderflow-reconcile', 'orderflow-resize']:
        assert name in existing, f"{name} is declared in Terraform but missing from the mock"


def test_terraform_rds_resources_exist(mock_rds):
    client = mock_rds["client"]
    existing = [d['DBInstanceIdentifier'] for d in client.describe_db_instances()['DBInstances']]
    for name in ['orderflow-primary', 'orderflow-reporting']:
        assert name in existing, f"{name} is declared in Terraform but missing from the mock"


def test_terraform_s3_resources_exist(mock_s3):
    client = mock_s3["client"]
    existing = [b['Name'] for b in client.list_buckets()['Buckets']]
    for name in ['orderflow-fixture-uploads-example', 'orderflow-fixture-reports-example', 'orderflow-fixture-archive-example']:
        assert name in existing, f"{name} is declared in Terraform but missing from the mock"


def test_terraform_sqs_resources_exist(mock_sqs):
    client = mock_sqs["client"]
    existing = [url.rsplit('/', 1)[-1] for url in client.list_queues().get('QueueUrls', [])]
    for name in ['orderflow-orders', 'orderflow-payments', 'orderflow-notifications']:
        assert name in existing, f"{name} is declared in Terraform but missing from the mock"


def test_every_terraform_resource_is_mocked(mock_aws_stack):
    """Guards against Terraform growing a resource that the test fixtures never create."""
    mocked = {name for bucket in mock_aws_stack.values() for name in bucket['names']}
    declared = {meta['name'] for meta in TERRAFORM_RESOURCES.values()}
    assert declared <= mocked, declared - mocked
